/**
 * The production pipeline over SYNTHETIC recordings (fixtures/synthetic,
 * generated by scripts/synthetic-fixtures.ts from tests/synthetic/cases.ts).
 * Expected values come from the case definitions, not from TxStory output.
 * Synthetic data exercises adapter and pipeline behaviour; it is not evidence
 * about real providers (see tests/captured for the opt-in captured suite).
 */
import { readFileSync, readdirSync } from 'node:fs';
import { beforeAll, describe, expect, it } from 'vitest';
import type { Story } from '../../src/core/types.js';
import { engineConfigFromEnv } from '../../src/engine/config.js';
import { checkReplay, readRecording, replayRecording, storyDigest, type Recording } from '../../src/engine/recording.js';
import type { StoryResult } from '../../src/engine/analyze.js';
import { A, ARB, LARGE, NFT, OP_USER, SEAPORT_BUYER, SEAPORT_SELLER, SWAP, WETH, allCases, ethFee, txHash } from '../synthetic/cases.js';

const DIR = 'fixtures/synthetic';
const vectors = JSON.parse(readFileSync('tests/vectors/abi-cast.json', 'utf8'));
const cases = allCases(vectors);
const config = engineConfigFromEnv({});
const results = new Map<string, StoryResult>();
const recordings = new Map<string, Recording>();

beforeAll(async () => {
  for (const f of readdirSync(DIR).filter((x) => x.endsWith('.json'))) {
    const rec = await readRecording(`${DIR}/${f}`);
    recordings.set(rec.hash, rec);
    results.set(rec.hash, await replayRecording(rec, config));
  }
});
const story = (id: string): Story => {
  const r = results.get(txHash(id));
  if (!r || r.kind !== 'ok') throw new Error(`${id}: ${r?.kind}`);
  return r.story;
};
const delta = (s: Story, address: string, asset: string) => s.ledger.find((r) => r.address === address.toLowerCase() && r.assetKey === asset.toLowerCase())?.delta;

describe('synthetic recordings: integrity', () => {
  it('one recording per case, all labelled synthetic', () => {
    expect([...recordings.values()].map((r) => r.hash).sort()).toEqual(cases.map((c) => c.hash).sort());
    for (const r of recordings.values()) {
      expect(r.origin).toBe('synthetic');
      expect(r.description).toMatch(/^Synthetic: /);
      expect(r.endpoints!.rpcs.every((e) => e.url.includes('.synthetic.invalid'))).toBe(true);
    }
    for (const r of results.values()) if (r.kind === 'ok') expect(r.story.mode).toBe('synthetic');
  });
  it('keeps every amount an exact integer string and conserves fungible supply', () => {
    for (const r of results.values()) {
      if (r.kind !== 'ok') continue;
      const s = r.story;
      for (const m of s.movements) expect(m.amount).toMatch(/^\d+$/);
      for (const [key, asset] of Object.entries(s.assets)) {
        if (asset.kind !== 'erc20') continue;
        const moves = s.movements.filter((m) => m.assetKey === key);
        const minted = moves.filter((m) => m.from === null).reduce((a, m) => a + BigInt(m.amount), 0n);
        const burned = moves.filter((m) => m.to === null).reduce((a, m) => a + BigInt(m.amount), 0n);
        expect(s.ledger.filter((l) => l.assetKey === key).reduce((a, l) => a + BigInt(l.delta), 0n), `${s.hash} ${key}`).toBe(minted - burned);
      }
    }
  });
  it('replays deterministically: same evidence and the same output digest as recorded', () => {
    for (const [hash, rec] of recordings) {
      const r = results.get(hash)!;
      if (r.kind !== 'ok') continue;
      expect(checkReplay(rec, r), hash).toMatchObject({ sameEvidence: true, sameOutput: true });
      expect(rec.output!.storySha256).toBe(storyDigest(r.story));
    }
  });
});

describe('synthetic cases: behaviour', () => {
  it('plain transfer: exact sender delta, fee split, all rows match the explorer', () => {
    const s = story('eth-transfer'); const f = ethFee(21_000n);
    expect(delta(s, A.sender, 'native')).toBe((-(250n * 10n ** 15n) - f.total).toString());
    expect(s.fees.total).toBe(f.total.toString());
    expect(s.fees.components.map((c) => [c.kind, c.amount])).toEqual([['fee-burn', f.burned.toString()], ['fee-tip', f.tip.toString()]]);
    expect(s.interpretations[0]!.kind).toBe('native-transfer');
    expect(s.crossCheck.summary).toMatchObject({ match: 3, mismatch: 0, onlyTxStory: 0, onlyExplorer: 0 });
  });
  it('failed transaction: only the fee moves; explorer revert reason is labelled', () => {
    const s = story('failed');
    expect(s.outcome).toBe('reverted');
    expect(s.movements.every((m) => m.kind.startsWith('fee'))).toBe(true);
    expect(s.interpretations[0]!.kind).toBe('failed');
    expect(s.tx.revertReason).toEqual({ text: 'execution reverted: transfer amount exceeds balance', source: 'explorer' });
  });
  it('fee-on-transfer swap: exact deltas, heuristic headline, explorer summary kept separate', () => {
    const s = story('swap-fee-on-transfer');
    expect(delta(s, A.sender, A.taxToken)).toBe((-(SWAP.tax + SWAP.toPair)).toString());
    expect(delta(s, A.sender, WETH)).toBe(SWAP.wethOut.toString());
    expect(delta(s, A.sender, 'native')).toBe((-ethFee(SWAP.gas).total).toString());
    expect(s.interpretations.filter((i) => i.kind !== 'protocol').map((i) => [i.kind, i.confidence])).toEqual([['swap', 'heuristic'], ['explorer-summary', 'explorer'], ['fee-on-transfer', 'heuristic']]);
    expect(s.interpretations.find((i) => i.kind === 'explorer-summary')!.detail).toBe('Swap 1000 TAXT for 0.5 WETH on Uniswap V2');
    expect(s.crossCheck.summary.mismatch).toBe(0);
  });
  it('fast stage: RPC only, cross-check reported as loading', async () => {
    const r = await replayRecording(recordings.get(txHash('swap-fee-on-transfer'))!, config, { stage: 'fast' });
    if (r.kind !== 'ok') throw new Error(r.kind);
    expect(r.story.crossCheck.reason).toMatch(/loading/);
    expect(r.story.sources.every((x) => x.kind === 'rpc')).toBe(true);
  });
  it('WETH unwrap: burn plus explorer-reported internal ETH, cross-check clean', () => {
    const s = story('weth-unwrap');
    expect(s.movements.some((m) => m.kind === 'unwrap-burn')).toBe(true);
    expect(s.movements.some((m) => m.kind === 'native-internal' && m.provenance === 'explorer')).toBe(true);
    expect(s.interpretations[0]!.kind).toBe('unwrap');
    expect(s.crossCheck.summary.mismatch).toBe(0);
  });
  it('explorer has not indexed the transaction (404): RPC-only story says so', () => {
    const s = story('weth-wrap-unindexed');
    expect(s.crossCheck.available).toBe(false);
    expect(s.crossCheck.reason).toMatch(/not indexed/);
    expect(s.movements.some((m) => m.kind === 'wrap-mint')).toBe(true);
    expect(s.assets[WETH]).toMatchObject({ symbol: 'WETH', decimals: 18, metadataSource: 'rpc-call' });
  });
  it('NFTs: ERC-721 ids and directions in the ledger; agreement compared by token id', () => {
    const s = story('nft-transfers');
    expect(s.ledger.find((r) => r.address === A.sender && r.assetKey === A.nft721)).toMatchObject({ delta: '-1', tokenIdsOut: [NFT.id721.toString()] });
    expect(s.ledger.find((r) => r.address === A.recipient && r.assetKey === A.nft721)).toMatchObject({ delta: '1', tokenIdsIn: [NFT.id721.toString()] });
    const rows721 = s.crossCheck.rows.filter((r) => r.assetKey === A.nft721);
    expect(rows721.map((r) => [r.scope, r.status])).toEqual([['token-ids', 'match'], ['token-ids', 'match']]);
    expect(s.movements.some((m) => s.assets[m.assetKey]?.kind === 'erc1155' && m.tokenId === NFT.id1155.toString())).toBe(true);
  });
  it('NFT identity: equal counts with a different token id is a mismatch', () => {
    const s = story('nft-id-disagreement');
    const rows721 = s.crossCheck.rows.filter((r) => r.assetKey === A.nft721);
    expect(rows721.every((r) => r.scope === 'token-ids' && r.status === 'mismatch')).toBe(true);
    expect(rows721.find((r) => r.address === A.sender)).toMatchObject({ txstoryTokenIds: { in: [], out: ['42'] }, explorerTokenIds: { in: [], out: ['43'] } });
  });
  it('contract creation is recognised', () => {
    const s = story('contract-creation');
    expect(s.tx.createdContract).toBe(A.deployed);
    expect(s.interpretations[0]!.kind).toBe('contract-creation');
  });
  it('pending transaction is reported as pending, not as an outage', () => {
    expect(results.get(txHash('pending'))!.kind).toBe('pending');
  });
  it('OP Stack deposit: no fee, labelled as a deposit', () => {
    const s = story('op-deposit');
    expect(s.fees.components).toEqual([]);
    expect(s.interpretations[0]!.headline).toMatch(/deposit transaction/);
  });
  it('OP Mainnet transfer: execution fee and L1 data fee itemised; explorer agrees', () => {
    const s = story('op-user');
    expect(s.fees.components.map((c) => [c.kind, c.amount])).toEqual([['fee-execution', (OP_USER.gas * OP_USER.price).toString()], ['fee-l1-data', OP_USER.l1Fee.toString()]]);
    expect(delta(s, A.sender, 'native')).toBe((-(OP_USER.value + OP_USER.gas * OP_USER.price + OP_USER.l1Fee)).toString());
    expect(s.crossCheck.summary.mismatch).toBe(0);
  });
  it('explorer refusal (403): RPC-only, reason recorded, native internal unavailable', () => {
    const s = story('base-explorer-403');
    expect(s.crossCheck.available).toBe(false);
    expect(s.sources.some((x) => x.kind === 'explorer' && x.httpStatus === 403)).toBe(true);
    expect(s.completeness.nativeInternal).toBe('unavailable');
    expect(s.warnings.join(' ')).toMatch(/Internal native-value movements are unavailable/);
  });
  it('Arbitrum: single fee component; token metadata from eth_call; exact amount', () => {
    const s = story('arbitrum-token-403');
    expect(s.fees.total).toBe((ARB.gas * ARB.price).toString());
    expect(s.assets[A.arbToken]).toMatchObject({ symbol: 'SYNA', decimals: 6, metadataSource: 'rpc-call' });
    expect(delta(s, A.recipient, A.arbToken)).toBe(ARB.amount.toString());
  });
  it('explorer timeout on internal transactions: native rows flagged as an expected gap; token rows agree', () => {
    const s = story('large-internal-timeout');
    expect(s.movements.filter((m) => m.kind === 'token-transfer')).toHaveLength(2 * LARGE.legs);
    expect(s.completeness).toMatchObject({ nativeInternal: 'unavailable', explorerTokenTransfers: 'complete' });
    expect(s.sources.filter((x) => x.method.endsWith('/token-transfers')).length).toBe(2); // two pages
    expect(s.warnings.join(' ')).toMatch(/timed out/);
    const native = s.crossCheck.rows.filter((r) => r.assetKey === 'native' && r.status !== 'match' && r.status !== 'not-comparable');
    expect(native.length).toBeGreaterThan(0);
    for (const r of native) expect(r.note).toMatch(/Expected gap/);
    expect(s.crossCheck.rows.filter((r) => r.assetKey !== 'native' && r.status === 'mismatch')).toEqual([]);
  });
  it('Seaport decoder module interprets the cast-encoded OrderFulfilled event', () => {
    const s = story('seaport-sale');
    const i = s.interpretations.find((x) => x.id === 'seaport:fulfilled:2')!;
    expect(i).toMatchObject({ kind: 'protocol', confidence: 'decoded', evidence: ['log:2'] });
    expect(i.detail).toContain(`Offerer ${SEAPORT_SELLER}`);
    expect(i.detail).toContain(`Recipient ${SEAPORT_BUYER}`);
    expect(i.headline).toBe('Seaport order fulfilled: 1 offered item(s) for 2 consideration item(s)');
  });
});
